def test_cross_check_tariff_routes_counts_combinations():
    zones = ["z1", "z2"]
    weights = [1, 0, 2]
    carriers = ["c1", "c2"]
    result = cross_check_tariff_routes(zones, weights, carriers)
    assert result == {"c1": 4, "c2": 4}


